    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    marks = [
        grid[r][c]
        for r in range(1, h - 1)
        for c in range(1, w - 1)
        if grid[r][c] != bg
    ]
    ray = Counter(marks).most_common(1)[0][0] if marks else bg
    out = [row[:] for row in grid]

    # Gather colored runs on each edge.
    sides = {
        "top": [(0, c) for c in range(w)],
        "bottom": [(h - 1, c) for c in range(w)],
        "left": [(r, 0) for r in range(h)],
        "right": [(r, w - 1) for r in range(h)],
    }
    runs = []
    for side, coords in sides.items():
        active = []
        for r, c in coords + [(-1, -1)]:
            if r >= 0 and grid[r][c] != bg:
                active.append((r, c))
            elif active:
                runs.append((side, active[:]))
                active = []

    # A corner belongs to both edges. Assign it to the longer adjoining
    # run, preventing a singleton corner from launching a spurious ray.
    corner_owner = {}
    for corner, a, b in [
        ((0, 0), "top", "left"), ((0, w - 1), "top", "right"),
        ((h - 1, 0), "bottom", "left"), ((h - 1, w - 1), "bottom", "right")
    ]:
        if grid[corner[0]][corner[1]] != bg:
            lengths = {}
            for side in (a, b):
                lengths[side] = max(
                    (len(run) for s, run in runs if s == side and corner in run),
                    default=0
                )
            corner_owner[corner] = a if lengths[a] >= lengths[b] else b

    for side, run in runs:
        dr, dc = {
            "top": (1, 0), "bottom": (-1, 0),
            "left": (0, 1), "right": (0, -1)
        }[side]
        for r, c in run:
            if (r, c) in corner_owner and corner_owner[(r, c)] != side:
                continue
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w:
                # Never overwrite another border source.
